const fs = await import('node:fs');
const path = process.env.PNG_PATH;
if (!path) throw new Error('PNG_PATH not set');
if (!fs.existsSync(path)) throw new Error('PNG file not found');
globalThis.pngPath = path;

const fs = await import('node:fs');
const upng = await import('@pdf-lib/upng');
const mod = upng.default || upng;
const UPNG = mod;
const data = await fs.promises.readFile(globalThis.pngPath);
const arrBuf = data.buffer.slice(data.byteOffset, data.byteOffset + data.byteLength);
const img = UPNG.decode(arrBuf);
const rgba = UPNG.toRGBA8(img)[0];
globalThis.rgbaBase64 = Buffer.from(rgba).toString('base64');
